import { GlobalSettingsPanel } from "@/components/global-settings/GlobalSettingsPanel"
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog"

type Props = {
  open: boolean
  onOpenChange: (open: boolean) => void
}

export function GlobalSettingsDialog({ open, onOpenChange }: Props) {
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="flex h-[85vh] max-h-[900px] flex-col overflow-hidden p-0 sm:max-w-5xl" aria-describedby={undefined}>
        <DialogHeader className="shrink-0 border-b border-border px-6 py-5">
          <DialogTitle>Settings</DialogTitle>
        </DialogHeader>
        <div
          data-slot="global-settings-body"
          className="min-h-0 flex-1 overflow-hidden"
          // Radix's document scroll lock sees the Shadow DOM host instead of
          // this sibling content shard. Keep scroll events local while letting
          // the browser perform native scrolling and child controls handle them.
          onWheel={(event) => event.stopPropagation()}
          onTouchMove={(event) => event.stopPropagation()}
        >
          <GlobalSettingsPanel />
        </div>
      </DialogContent>
    </Dialog>
  )
}
