import { useCallback, useEffect, useMemo, useState } from "react"
import { Copy, ExternalLink, Trash2 } from "lucide-react"
import { Alert, AlertDescription } from "@/components/ui/alert"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Switch } from "@/components/ui/switch"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import { getAdminParams } from "@/lib/admin-params"
import {
  buildSupportMagicLink,
  createSupportToken,
  deleteSupportToken,
  listSupportTokens,
  normalizeAllowedShortcodes,
  saveGlobalOptions,
  type SupportToken,
} from "@/lib/global-settings-api"

type Message = {
  kind: "success" | "error"
  text: string
} | null

function errorText(error: unknown, fallback: string): string {
  return error instanceof Error && error.message ? error.message : fallback
}

async function copyText(value: string): Promise<boolean> {
  if (!value) return false
  try {
    await navigator.clipboard.writeText(value)
    return true
  } catch {
    const textarea = document.createElement("textarea")
    textarea.value = value
    textarea.setAttribute("readonly", "")
    textarea.style.position = "fixed"
    textarea.style.left = "-9999px"
    document.body.appendChild(textarea)
    textarea.select()
    const copied = document.execCommand("copy")
    textarea.remove()
    return copied
  }
}

function formatTokenDate(value?: string | null): string {
  if (!value) return "Never used"
  const date = new Date(value)
  return Number.isNaN(date.getTime()) ? value : date.toLocaleDateString()
}

export function GeneralSettingsPage() {
  const params = useMemo(() => getAdminParams(), [])
  const options = useMemo(
    () =>
      params.options && typeof params.options === "object"
        ? (params.options as Record<string, unknown>)
        : {},
    [params.options],
  )

  const [googleApiKey, setGoogleApiKey] = useState(
    typeof options.google_api_key === "string" ? options.google_api_key : "",
  )
  const [googleGeocodingApiKey, setGoogleGeocodingApiKey] = useState(
    typeof options.google_geocoding_api_key === "string" ? options.google_geocoding_api_key : "",
  )
  const [allowedShortcodes, setAllowedShortcodes] = useState(
    normalizeAllowedShortcodes(options.allowed_shortcodes).join(", "),
  )
  const [saving, setSaving] = useState(false)
  const [settingsMessage, setSettingsMessage] = useState<Message>(null)

  const [accessLogs, setAccessLogs] = useState(false)
  const [accessWp, setAccessWp] = useState(false)
  const [tokens, setTokens] = useState<SupportToken[]>([])
  const [tokensLoading, setTokensLoading] = useState(false)
  const [tokenBusy, setTokenBusy] = useState(false)
  const [supportMessage, setSupportMessage] = useState<Message>(null)
  const [magicLink, setMagicLink] = useState("")
  const supportAvailable = params.license != null

  const loadTokens = useCallback(async () => {
    if (!supportAvailable || !params.user.isAdmin) return
    setTokensLoading(true)
    try {
      setTokens(await listSupportTokens())
    } catch (error) {
      setSupportMessage({
        kind: "error",
        text: errorText(error, "Could not load support access tokens."),
      })
    } finally {
      setTokensLoading(false)
    }
  }, [params.user.isAdmin, supportAvailable])

  useEffect(() => {
    void loadTokens()
  }, [loadTokens])

  useEffect(() => {
    const onAiSettingsMutation = (event: Event) => {
      const detail = (event as CustomEvent<{
        settings?: { allowedShortcodes?: unknown }
      }>).detail
      const next = detail?.settings?.allowedShortcodes
      if (Array.isArray(next)) {
        setAllowedShortcodes(
          next.filter((item): item is string => typeof item === "string").join(", "),
        )
      }
      setSettingsMessage({ kind: "success", text: "Settings updated by AI." })
    }

    window.addEventListener("mapsvg:global-settings-mutation", onAiSettingsMutation)
    return () =>
      window.removeEventListener("mapsvg:global-settings-mutation", onAiSettingsMutation)
  }, [])

  const saveSettings = async () => {
    setSaving(true)
    setSettingsMessage(null)
    try {
      const payload: Record<string, unknown> = {
        google_api_key: googleApiKey.trim(),
        google_geocoding_api_key: googleGeocodingApiKey.trim(),
      }
      if (params.user.isAdmin) {
        payload.allowed_shortcodes = normalizeAllowedShortcodes(allowedShortcodes)
      }
      await saveGlobalOptions(payload)
      setAllowedShortcodes(
        params.user.isAdmin
          ? normalizeAllowedShortcodes(allowedShortcodes).join(", ")
          : allowedShortcodes,
      )
      setSettingsMessage({ kind: "success", text: "Settings saved." })
    } catch (error) {
      setSettingsMessage({
        kind: "error",
        text: errorText(error, "Could not save settings."),
      })
    } finally {
      setSaving(false)
    }
  }

  const createToken = async () => {
    if (!params.user.isAdmin) return
    if (!accessLogs) {
      setSupportMessage({
        kind: "error",
        text: 'Enable "Access to logs" before creating a support token.',
      })
      return
    }

    setTokenBusy(true)
    setSupportMessage(null)
    setMagicLink("")
    try {
      const token = await createSupportToken({
        logs: true,
        ...(accessWp ? { wp: true } : {}),
      })
      const link = buildSupportMagicLink(params.homeUrl, token)
      if (!link) {
        throw new Error("MapSVG did not return a usable support token.")
      }
      setMagicLink(link)
      const copied = await copyText(link)
      setSupportMessage({
        kind: "success",
        text: copied
          ? "Magic link created and copied to the clipboard. Save it now: it is shown only once."
          : "Magic link created. Save it now: it is shown only once.",
      })
      setAccessLogs(false)
      setAccessWp(false)
      await loadTokens()
    } catch (error) {
      setSupportMessage({
        kind: "error",
        text: errorText(error, "Could not create a support token."),
      })
    } finally {
      setTokenBusy(false)
    }
  }

  const removeToken = async (token: SupportToken) => {
    if (!params.user.isAdmin) return
    if (!window.confirm("Delete this support access token?")) return

    setTokenBusy(true)
    setSupportMessage(null)
    try {
      await deleteSupportToken(token.id)
      setTokens((current) => current.filter((item) => item.id !== token.id))
      setSupportMessage({ kind: "success", text: "Support access token deleted." })
    } catch (error) {
      setSupportMessage({
        kind: "error",
        text: errorText(error, "Could not delete the support access token."),
      })
    } finally {
      setTokenBusy(false)
    }
  }

  return (
    <div className="flex flex-col gap-6">
      <div>
        <h1 className="text-2xl font-semibold tracking-tight">Settings</h1>
        <p className="mt-1 text-sm text-muted-foreground">
          Global MapSVG settings for this WordPress installation.
        </p>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>Map services</CardTitle>
        </CardHeader>
        <CardContent className="space-y-5">
          <div className="grid gap-2">
            <Label htmlFor="mapsvg-google-api-key">Google Maps API key</Label>
            <Input
              id="mapsvg-google-api-key"
              value={googleApiKey}
              onChange={(event) => setGoogleApiKey(event.target.value)}
              autoComplete="off"
            />
          </div>

          <div className="grid gap-2">
            <Label htmlFor="mapsvg-google-geocoding-api-key">Google Geocoding API key</Label>
            <Input
              id="mapsvg-google-geocoding-api-key"
              value={googleGeocodingApiKey}
              onChange={(event) => setGoogleGeocodingApiKey(event.target.value)}
              autoComplete="off"
            />
            <p className="text-sm text-muted-foreground">
              Google Geocoding API is used to convert address to lat/lng coordinates and back.
            </p>
          </div>

          <div className="grid gap-2">
            <Label htmlFor="mapsvg-allowed-shortcodes">Allowed shortcodes</Label>
            <Input
              id="mapsvg-allowed-shortcodes"
              value={allowedShortcodes}
              onChange={(event) => setAllowedShortcodes(event.target.value)}
              disabled={!params.user.isAdmin}
            />
            <p className="text-sm text-muted-foreground">
              Comma-separated list of shortcodes that are allowed to be used in map templates. Can
              be edited by site Admins only.
            </p>
          </div>

          {settingsMessage ? (
            <Alert variant={settingsMessage.kind === "error" ? "destructive" : "success"}>
              <AlertDescription>{settingsMessage.text}</AlertDescription>
            </Alert>
          ) : null}

          <Button type="button" onClick={() => void saveSettings()} disabled={saving}>
            {saving ? "Saving..." : "Save"}
          </Button>
        </CardContent>
      </Card>

      {supportAvailable ? (
        <Card>
          <CardHeader>
            <CardTitle>Access for support</CardTitle>
            <CardDescription>
              Please grant the MapSVG support team some level of access when submitting a bug report
              for quicker issue resolution. The more access you grant, the faster the issue can be
              resolved, but at least Access to logs is required.
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-6">
            {!params.user.isAdmin ? (
              <Alert variant="warning">
                <AlertDescription>
                  Only WordPress administrators can create or revoke support access.
                </AlertDescription>
              </Alert>
            ) : (
              <>
                <div className="space-y-5">
                  <div className="flex items-start justify-between gap-5">
                    <div className="space-y-1">
                      <Label htmlFor="mapsvg-support-logs">Access to logs</Label>
                      <p className="text-sm text-muted-foreground">
                        Grants access to WordPress logs, database queries, and other diagnostic
                        information. This access level is required.
                      </p>
                    </div>
                    <Switch
                      id="mapsvg-support-logs"
                      checked={accessLogs}
                      onCheckedChange={setAccessLogs}
                      disabled={tokenBusy}
                    />
                  </div>

                  <div className="flex items-start justify-between gap-5">
                    <div className="space-y-1">
                      <Label htmlFor="mapsvg-support-wp">Access to WP-admin</Label>
                      <p className="text-sm text-muted-foreground">
                        Creates an administrator user named "mapsvg". The user is removed when all
                        access tokens with WP-admin permission are deleted.
                      </p>
                    </div>
                    <Switch
                      id="mapsvg-support-wp"
                      checked={accessWp}
                      onCheckedChange={setAccessWp}
                      disabled={tokenBusy}
                    />
                  </div>
                </div>

                <Button
                  type="button"
                  onClick={() => void createToken()}
                  disabled={tokenBusy || !accessLogs}
                >
                  {tokenBusy ? "Working..." : "Create access token"}
                </Button>

                {magicLink ? (
                  <div className="space-y-2">
                    <Label htmlFor="mapsvg-support-magic-link">Magic link</Label>
                    <div className="flex gap-2">
                      <Input
                        id="mapsvg-support-magic-link"
                        value={magicLink}
                        readOnly
                        className="font-mono text-xs"
                      />
                      <Button
                        type="button"
                        variant="outline"
                        size="icon"
                        aria-label="Copy magic link"
                        onClick={() => void copyText(magicLink)}
                      >
                        <Copy />
                      </Button>
                    </div>
                  </div>
                ) : null}

                {supportMessage ? (
                  <Alert variant={supportMessage.kind === "error" ? "destructive" : "success"}>
                    <AlertDescription>{supportMessage.text}</AlertDescription>
                  </Alert>
                ) : null}

                <div className="space-y-3">
                  <div className="flex items-center justify-between gap-3">
                    <h3 className="text-sm font-semibold">Access tokens</h3>
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      onClick={() => void loadTokens()}
                      disabled={tokensLoading || tokenBusy}
                    >
                      Refresh
                    </Button>
                  </div>

                  {tokensLoading ? (
                    <p className="text-sm text-muted-foreground">Loading access tokens...</p>
                  ) : tokens.length === 0 ? (
                    <p className="text-sm text-muted-foreground">
                      No active support access tokens.
                    </p>
                  ) : (
                    <div className="rounded-md border">
                      <Table>
                        <TableHeader>
                          <TableRow>
                            <TableHead>Token</TableHead>
                            <TableHead>Created</TableHead>
                            <TableHead>Last used</TableHead>
                            <TableHead>Access to</TableHead>
                            <TableHead className="w-12" />
                          </TableRow>
                        </TableHeader>
                        <TableBody>
                          {tokens.map((token) => (
                            <TableRow key={token.id}>
                              <TableCell className="font-mono">
                                {token.tokenFirstFour || "????"}****
                              </TableCell>
                              <TableCell>{formatTokenDate(token.createdAt)}</TableCell>
                              <TableCell>{formatTokenDate(token.lastUsedAt)}</TableCell>
                              <TableCell>
                                <div className="flex flex-wrap gap-1">
                                  {Object.entries(token.accessRights)
                                    .filter(([, enabled]) => enabled)
                                    .map(([right]) => (
                                      <Badge key={right} variant="secondary">
                                        {right}
                                      </Badge>
                                    ))}
                                </div>
                              </TableCell>
                              <TableCell>
                                <Button
                                  type="button"
                                  variant="ghost"
                                  size="icon"
                                  aria-label="Delete support access token"
                                  disabled={tokenBusy}
                                  onClick={() => void removeToken(token)}
                                >
                                  <Trash2 />
                                </Button>
                              </TableCell>
                            </TableRow>
                          ))}
                        </TableBody>
                      </Table>
                    </div>
                  )}
                </div>

                <p className="text-xs text-muted-foreground">
                  Need to manage support from your MapSVG account?{" "}
                  <a
                    href="https://mapsvg.com/dashboard"
                    target="_blank"
                    rel="noreferrer"
                    className="inline-flex items-center gap-1 underline underline-offset-4"
                  >
                    MapSVG Dashboard <ExternalLink className="size-3" />
                  </a>
                </p>
              </>
            )}
          </CardContent>
        </Card>
      ) : null}
    </div>
  )
}
